def _ts_project_module_impl(ctx):
    runfiles = ctx.attr.dep[DefaultInfo].default_runfiles
    info = ctx.attr.dep[JsInfo]
    filtered_runfiles = []
    for f in runfiles.files.to_list():
        if f.short_path.startswith('node_modules/'):
            continue
        filtered_runfiles.append(f)
    runfiles = ctx.runfiles(files=filtered_runfiles)
    providers = [DefaultInfo(runfiles=runfiles), JSModuleInfo(direct_sources=info.sources, sources=depset(transitive=[info.transitive_sources])), JSEcmaScriptModuleInfo(direct_sources=info.sources, sources=depset(transitive=[info.transitive_sources])), DeclarationInfo(declarations=_filter_types_depset(info.types), transitive_declarations=_filter_types_depset(info.transitive_types), type_blocklisted_declarations=depset())]
    if ctx.attr.module_name:
        providers.append(LinkablePackageInfo(package_name=ctx.attr.module_name, package_path='', path='%s/%s/%s' % (ctx.bin_dir.path, ctx.label.workspace_root, ctx.label.package), files=info.sources))
    return providers

